-- 도커 세트 337. 여러 번 실행해도 안전하다 (NOT EXISTS 가드). 단원·display_order 는 통합 시 별도로 정한다. 원본: 02_quest_set.sql, 03_quest_set337.sql. docs/specs/spec_docker_image_manage_set.md
INSERT INTO quest_set (id, title, description, sandbox_type, category)
SELECT 337, '도커 이미지 관리와 옮기기 실습: pull 태그, images --format, tag, rmi, prune, commit, save·load, export·import', '/tmp/work 에서 alpine 이미지를 직접 받고, 태그를 붙이고, 지우고, 정리하고, 커밋하고, tar 로 저장·불러오기·내보내기·가져오기를 해 봅니다. 이미지 존재 여부와 태그, tar 파일 목록, 컨테이너 개수로 결과를 확인하면서 한 단계씩 익힙니다.', 'docker', '도커'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest_set WHERE id = 337);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 337, 1, '태그를 지정해서 이미지 받기', '`alpine` 이미지의 **`3.19`** 버전을 받으세요. (태그를 안 쓰면 최신 `latest` 가 받아집니다)', '`docker pull 이름:태그` 형태로 콜론 뒤에 버전을 적어요. 받은 뒤 `docker images` 로 TAG 칸을 확인해 보세요.', 'docker pull alpine:3.19
docker images alpine

# 이름:태그 로 받으면 그 버전만 받는다. 태그를 생략하면 latest', '["sh", "-c", "docker rm -f $(docker ps -aq) >/dev/null 2>&1; docker rmi -f $(docker images -aq) >/dev/null 2>&1; rm -rf /tmp/work; mkdir -p /tmp/work; docker pull -q alpine >/dev/null 2>&1; true"]', '["sh", "-c", "( docker image inspect alpine:3.19 >/dev/null 2>&1 )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "alpine:3.19 이미지가 있다", "cmd": ["sh", "-c", "docker image inspect alpine:3.19 >/dev/null 2>&1"]}]', '[{"title": "Docker 공식 문서: docker image pull", "url": "https://docs.docker.com/reference/cli/docker/image/pull/"}, {"title": "Docker 공식 문서: docker image ls", "url": "https://docs.docker.com/reference/cli/docker/image/ls/"}, {"title": "Docker 공식 문서: docker image tag", "url": "https://docs.docker.com/reference/cli/docker/image/tag/"}, {"title": "Docker 공식 문서: docker image rm", "url": "https://docs.docker.com/reference/cli/docker/image/rm/"}, {"title": "Docker 공식 문서: docker image prune", "url": "https://docs.docker.com/reference/cli/docker/image/prune/"}, {"title": "Docker 공식 문서: docker container commit", "url": "https://docs.docker.com/reference/cli/docker/container/commit/"}, {"title": "Docker 공식 문서: docker image inspect", "url": "https://docs.docker.com/reference/cli/docker/image/inspect/"}, {"title": "Docker 공식 문서: docker image save", "url": "https://docs.docker.com/reference/cli/docker/image/save/"}, {"title": "Docker 공식 문서: docker image load", "url": "https://docs.docker.com/reference/cli/docker/image/load/"}, {"title": "Docker 공식 문서: docker container export", "url": "https://docs.docker.com/reference/cli/docker/container/export/"}, {"title": "Docker 공식 문서: docker image import", "url": "https://docs.docker.com/reference/cli/docker/image/import/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 337 AND order_index = 1);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 337, 2, '이미지 목록을 이름:태그로 저장', '이미지 `alpine` 이 두 가지 태그로 받아져 있습니다. `docker images` 가 표 대신 **`이름:태그`** 한 줄씩 출력하게 해서 `/tmp/work/images.txt` 에 저장하세요.', '`docker images` 에는 `--format` 옵션이 있어요. 템플릿에서 이름은 `{{.Repository}}`, 태그는 `{{.Tag}}` 입니다. 둘 사이에 콜론을 직접 적으세요.', 'docker images --format ''{{.Repository}}:{{.Tag}}'' > /tmp/work/images.txt
cat /tmp/work/images.txt

# 헤더 줄 없이 원하는 칸만 뽑을 수 있다', '["sh", "-c", "docker rm -f $(docker ps -aq) >/dev/null 2>&1; docker rmi -f $(docker images -aq) >/dev/null 2>&1; rm -rf /tmp/work; mkdir -p /tmp/work; docker pull -q alpine >/dev/null 2>&1; docker pull -q alpine:3.19 >/dev/null 2>&1; true"]', '["sh", "-c", "( grep -qx \\"alpine:3.19\\" /tmp/work/images.txt ) && ( [ \\"$(sort /tmp/work/images.txt)\\" = \\"$(docker images --format ''{{.Repository}}:{{.Tag}}'' | sort)\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "3.19 태그 줄이 이름:태그 형태로 있다", "cmd": ["sh", "-c", "grep -qx \\"alpine:3.19\\" /tmp/work/images.txt"]}, {"label": "파일이 현재 이미지 목록과 같다", "cmd": ["sh", "-c", "[ \\"$(sort /tmp/work/images.txt)\\" = \\"$(docker images --format ''{{.Repository}}:{{.Tag}}'' | sort)\\" ]"]}]', '[{"title": "Docker 공식 문서: docker image pull", "url": "https://docs.docker.com/reference/cli/docker/image/pull/"}, {"title": "Docker 공식 문서: docker image ls", "url": "https://docs.docker.com/reference/cli/docker/image/ls/"}, {"title": "Docker 공식 문서: docker image tag", "url": "https://docs.docker.com/reference/cli/docker/image/tag/"}, {"title": "Docker 공식 문서: docker image rm", "url": "https://docs.docker.com/reference/cli/docker/image/rm/"}, {"title": "Docker 공식 문서: docker image prune", "url": "https://docs.docker.com/reference/cli/docker/image/prune/"}, {"title": "Docker 공식 문서: docker container commit", "url": "https://docs.docker.com/reference/cli/docker/container/commit/"}, {"title": "Docker 공식 문서: docker image inspect", "url": "https://docs.docker.com/reference/cli/docker/image/inspect/"}, {"title": "Docker 공식 문서: docker image save", "url": "https://docs.docker.com/reference/cli/docker/image/save/"}, {"title": "Docker 공식 문서: docker image load", "url": "https://docs.docker.com/reference/cli/docker/image/load/"}, {"title": "Docker 공식 문서: docker container export", "url": "https://docs.docker.com/reference/cli/docker/container/export/"}, {"title": "Docker 공식 문서: docker image import", "url": "https://docs.docker.com/reference/cli/docker/image/import/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 337 AND order_index = 2);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 337, 3, '이미지에 별명 붙이기 (tag)', '이미지 `alpine:3.19` 에 **`myapp:v1`** 이라는 새 이름을 붙이세요. 복사본이 아니라 같은 이미지에 이름만 하나 더 생겨야 합니다.', '`docker tag 원본 새이름` 형태입니다. 확인은 `docker images` 에서 두 줄의 IMAGE ID 가 같은지 보면 돼요.', 'docker tag alpine:3.19 myapp:v1
docker images

# 두 이름의 IMAGE ID 가 같다. 이름(태그)만 늘어난 것', '["sh", "-c", "docker rm -f $(docker ps -aq) >/dev/null 2>&1; docker rmi -f $(docker images -aq) >/dev/null 2>&1; rm -rf /tmp/work; mkdir -p /tmp/work; docker pull -q alpine >/dev/null 2>&1; docker pull -q alpine:3.19 >/dev/null 2>&1; true"]', '["sh", "-c", "( docker image inspect myapp:v1 >/dev/null 2>&1 ) && ( [ \\"$(docker image inspect -f ''{{.Id}}'' myapp:v1)\\" = \\"$(docker image inspect -f ''{{.Id}}'' alpine:3.19)\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "myapp:v1 이 있다", "cmd": ["sh", "-c", "docker image inspect myapp:v1 >/dev/null 2>&1"]}, {"label": "alpine:3.19 와 ID 가 같다", "cmd": ["sh", "-c", "[ \\"$(docker image inspect -f ''{{.Id}}'' myapp:v1)\\" = \\"$(docker image inspect -f ''{{.Id}}'' alpine:3.19)\\" ]"]}]', '[{"title": "Docker 공식 문서: docker image pull", "url": "https://docs.docker.com/reference/cli/docker/image/pull/"}, {"title": "Docker 공식 문서: docker image ls", "url": "https://docs.docker.com/reference/cli/docker/image/ls/"}, {"title": "Docker 공식 문서: docker image tag", "url": "https://docs.docker.com/reference/cli/docker/image/tag/"}, {"title": "Docker 공식 문서: docker image rm", "url": "https://docs.docker.com/reference/cli/docker/image/rm/"}, {"title": "Docker 공식 문서: docker image prune", "url": "https://docs.docker.com/reference/cli/docker/image/prune/"}, {"title": "Docker 공식 문서: docker container commit", "url": "https://docs.docker.com/reference/cli/docker/container/commit/"}, {"title": "Docker 공식 문서: docker image inspect", "url": "https://docs.docker.com/reference/cli/docker/image/inspect/"}, {"title": "Docker 공식 문서: docker image save", "url": "https://docs.docker.com/reference/cli/docker/image/save/"}, {"title": "Docker 공식 문서: docker image load", "url": "https://docs.docker.com/reference/cli/docker/image/load/"}, {"title": "Docker 공식 문서: docker container export", "url": "https://docs.docker.com/reference/cli/docker/container/export/"}, {"title": "Docker 공식 문서: docker image import", "url": "https://docs.docker.com/reference/cli/docker/image/import/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 337 AND order_index = 3);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 337, 4, '태그를 지우면 이미지도 지워질까', '`docker tag alpine:3.19 myapp:v1` 로 같은 이미지에 이름이 둘 붙어 있습니다. 여기서 `docker rmi myapp:v1` 을 실행하면 어떻게 될까요?', '이미지는 ID 로 하나이고 태그는 거기 붙은 이름표라는 점을 떠올려 보세요. 이름표가 하나 더 남아 있다면요?', NULL, NULL, '[]', 'choice', '["이미지 자체가 지워져서 `alpine:3.19` 도 함께 사라진다", "다른 이름이 붙어 있어서 항상 오류가 나고 지워지지 않는다", "`alpine:3.19` 만 남기고 레이어가 모두 새로 받아진다", "`myapp:v1` 이름표만 떨어지고 `alpine:3.19` 와 이미지 내용은 그대로 남는다"]', 3, '같은 ID 에 이름표(태그)가 둘 있을 때 `rmi` 는 **지정한 이름표만** 뗍니다(`Untagged`). 마지막 이름표를 뗄 때 비로소 이미지 레이어가 삭제돼요(`Deleted`). 그래서 이미지를 지웠는데 공간이 안 줄었다면 다른 태그가 남아 있는지 보면 됩니다.', NULL, NULL, NULL, '[{"title": "Docker 공식 문서: docker image pull", "url": "https://docs.docker.com/reference/cli/docker/image/pull/"}, {"title": "Docker 공식 문서: docker image ls", "url": "https://docs.docker.com/reference/cli/docker/image/ls/"}, {"title": "Docker 공식 문서: docker image tag", "url": "https://docs.docker.com/reference/cli/docker/image/tag/"}, {"title": "Docker 공식 문서: docker image rm", "url": "https://docs.docker.com/reference/cli/docker/image/rm/"}, {"title": "Docker 공식 문서: docker image prune", "url": "https://docs.docker.com/reference/cli/docker/image/prune/"}, {"title": "Docker 공식 문서: docker container commit", "url": "https://docs.docker.com/reference/cli/docker/container/commit/"}, {"title": "Docker 공식 문서: docker image inspect", "url": "https://docs.docker.com/reference/cli/docker/image/inspect/"}, {"title": "Docker 공식 문서: docker image save", "url": "https://docs.docker.com/reference/cli/docker/image/save/"}, {"title": "Docker 공식 문서: docker image load", "url": "https://docs.docker.com/reference/cli/docker/image/load/"}, {"title": "Docker 공식 문서: docker container export", "url": "https://docs.docker.com/reference/cli/docker/container/export/"}, {"title": "Docker 공식 문서: docker image import", "url": "https://docs.docker.com/reference/cli/docker/image/import/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 337 AND order_index = 4);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 337, 5, '컨테이너가 쓰는 이미지 지우기', '이미지 `alpine:3.19` 로 만든 컨테이너 `keeper` 가 (종료된 채) 남아 있습니다. 먼저 `docker rmi alpine:3.19` 를 해 보고 막히는 이유를 읽은 뒤, **컨테이너와 이미지를 둘 다** 지우세요.', '이미지는 그 이미지로 만든 컨테이너가 있으면 지워지지 않아요(종료된 컨테이너도 포함). 컨테이너를 먼저 지운 뒤 이미지를 지우면 됩니다. `-f` 로 강제할 수도 있지만 컨테이너는 남아요.', 'docker rmi alpine:3.19      # 오류: 컨테이너가 이 이미지를 쓰는 중
docker rm keeper
docker rmi alpine:3.19
docker images

# 순서: 컨테이너 삭제 -> 이미지 삭제', '["sh", "-c", "docker rm -f $(docker ps -aq) >/dev/null 2>&1; docker rmi -f $(docker images -aq) >/dev/null 2>&1; rm -rf /tmp/work; mkdir -p /tmp/work; docker pull -q alpine >/dev/null 2>&1; docker pull -q alpine:3.19 >/dev/null 2>&1; docker run --name keeper alpine:3.19 true >/dev/null 2>&1; true"]', '["sh", "-c", "( ! docker image inspect alpine:3.19 >/dev/null 2>&1 ) && ( ! docker inspect keeper >/dev/null 2>&1 )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "alpine:3.19 이미지가 없다", "cmd": ["sh", "-c", "! docker image inspect alpine:3.19 >/dev/null 2>&1"]}, {"label": "keeper 컨테이너가 없다", "cmd": ["sh", "-c", "! docker inspect keeper >/dev/null 2>&1"]}]', '[{"title": "Docker 공식 문서: docker image pull", "url": "https://docs.docker.com/reference/cli/docker/image/pull/"}, {"title": "Docker 공식 문서: docker image ls", "url": "https://docs.docker.com/reference/cli/docker/image/ls/"}, {"title": "Docker 공식 문서: docker image tag", "url": "https://docs.docker.com/reference/cli/docker/image/tag/"}, {"title": "Docker 공식 문서: docker image rm", "url": "https://docs.docker.com/reference/cli/docker/image/rm/"}, {"title": "Docker 공식 문서: docker image prune", "url": "https://docs.docker.com/reference/cli/docker/image/prune/"}, {"title": "Docker 공식 문서: docker container commit", "url": "https://docs.docker.com/reference/cli/docker/container/commit/"}, {"title": "Docker 공식 문서: docker image inspect", "url": "https://docs.docker.com/reference/cli/docker/image/inspect/"}, {"title": "Docker 공식 문서: docker image save", "url": "https://docs.docker.com/reference/cli/docker/image/save/"}, {"title": "Docker 공식 문서: docker image load", "url": "https://docs.docker.com/reference/cli/docker/image/load/"}, {"title": "Docker 공식 문서: docker container export", "url": "https://docs.docker.com/reference/cli/docker/container/export/"}, {"title": "Docker 공식 문서: docker image import", "url": "https://docs.docker.com/reference/cli/docker/image/import/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 337 AND order_index = 5);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 337, 6, '이름 잃은 이미지 정리 (dangling)', '`tmp:1` 이름을 두 번 커밋한 탓에 이름이 없는(`<none>`) 이전 이미지가 남아 있습니다. **이름 없는 이미지만** 지우세요. `tmp:1` 과 컨테이너 `c1` 은 그대로 있어야 합니다.', '`docker image prune` 은 기본적으로 이름 없는(dangling) 이미지만 지워요. 확인 질문을 건너뛰는 옵션도 있습니다. 모든 안 쓰는 이미지를 지우는 `-a` 는 쓰면 안 돼요. `docker images -f dangling=true` 로 먼저 눈으로 보세요.', 'docker images -f dangling=true
docker image prune -f
docker images -f dangling=true
docker images

# -a 없이 쓰면 dangling 만 지운다. tmp:1 은 이름이 있으니 남는다', '["sh", "-c", "docker rm -f $(docker ps -aq) >/dev/null 2>&1; docker rmi -f $(docker images -aq) >/dev/null 2>&1; rm -rf /tmp/work; mkdir -p /tmp/work; docker pull -q alpine >/dev/null 2>&1; docker run --name c1 alpine sh -c ''echo a > /a'' >/dev/null 2>&1; docker commit c1 tmp:1 >/dev/null; sleep 1; docker commit c1 tmp:1 >/dev/null; true"]', '["sh", "-c", "( [ -z \\"$(docker images -f dangling=true -q)\\" ] ) && ( docker image inspect tmp:1 >/dev/null 2>&1 ) && ( docker inspect c1 >/dev/null 2>&1 )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "이름 없는 이미지가 없다", "cmd": ["sh", "-c", "[ -z \\"$(docker images -f dangling=true -q)\\" ]"]}, {"label": "tmp:1 이 남아 있다", "cmd": ["sh", "-c", "docker image inspect tmp:1 >/dev/null 2>&1"]}, {"label": "c1 컨테이너가 남아 있다", "cmd": ["sh", "-c", "docker inspect c1 >/dev/null 2>&1"]}]', '[{"title": "Docker 공식 문서: docker image pull", "url": "https://docs.docker.com/reference/cli/docker/image/pull/"}, {"title": "Docker 공식 문서: docker image ls", "url": "https://docs.docker.com/reference/cli/docker/image/ls/"}, {"title": "Docker 공식 문서: docker image tag", "url": "https://docs.docker.com/reference/cli/docker/image/tag/"}, {"title": "Docker 공식 문서: docker image rm", "url": "https://docs.docker.com/reference/cli/docker/image/rm/"}, {"title": "Docker 공식 문서: docker image prune", "url": "https://docs.docker.com/reference/cli/docker/image/prune/"}, {"title": "Docker 공식 문서: docker container commit", "url": "https://docs.docker.com/reference/cli/docker/container/commit/"}, {"title": "Docker 공식 문서: docker image inspect", "url": "https://docs.docker.com/reference/cli/docker/image/inspect/"}, {"title": "Docker 공식 문서: docker image save", "url": "https://docs.docker.com/reference/cli/docker/image/save/"}, {"title": "Docker 공식 문서: docker image load", "url": "https://docs.docker.com/reference/cli/docker/image/load/"}, {"title": "Docker 공식 문서: docker container export", "url": "https://docs.docker.com/reference/cli/docker/container/export/"}, {"title": "Docker 공식 문서: docker image import", "url": "https://docs.docker.com/reference/cli/docker/image/import/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 337 AND order_index = 6);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 337, 7, '컨테이너를 새 이미지로 만들기 (commit)', '컨테이너 `work` 안에는 `/greeting` 파일이 있습니다(내용 `hi`). 이 컨테이너를 **`greeter:1`** 이미지로 만드세요. 새 이미지로 컨테이너를 만들면 `/greeting` 이 그대로 있어야 합니다.', '`docker commit 컨테이너 새이미지:태그` 형태입니다. 만든 뒤 `docker run --rm greeter:1 cat /greeting` 으로 확인해 보세요.', 'docker commit work greeter:1
docker images greeter
docker run --rm greeter:1 cat /greeting

# commit 은 컨테이너의 변경분(파일)을 새 이미지 레이어로 굳힌다', '["sh", "-c", "docker rm -f $(docker ps -aq) >/dev/null 2>&1; docker rmi -f $(docker images -aq) >/dev/null 2>&1; rm -rf /tmp/work; mkdir -p /tmp/work; docker pull -q alpine >/dev/null 2>&1; docker run --name work alpine sh -c ''echo hi > /greeting'' >/dev/null 2>&1; true"]', '["sh", "-c", "( docker image inspect greeter:1 >/dev/null 2>&1 ) && ( [ \\"$(docker run --rm greeter:1 cat /greeting)\\" = hi ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "greeter:1 이 있다", "cmd": ["sh", "-c", "docker image inspect greeter:1 >/dev/null 2>&1"]}, {"label": "이미지 안 /greeting 이 hi 다", "cmd": ["sh", "-c", "[ \\"$(docker run --rm greeter:1 cat /greeting)\\" = hi ]"]}]', '[{"title": "Docker 공식 문서: docker image pull", "url": "https://docs.docker.com/reference/cli/docker/image/pull/"}, {"title": "Docker 공식 문서: docker image ls", "url": "https://docs.docker.com/reference/cli/docker/image/ls/"}, {"title": "Docker 공식 문서: docker image tag", "url": "https://docs.docker.com/reference/cli/docker/image/tag/"}, {"title": "Docker 공식 문서: docker image rm", "url": "https://docs.docker.com/reference/cli/docker/image/rm/"}, {"title": "Docker 공식 문서: docker image prune", "url": "https://docs.docker.com/reference/cli/docker/image/prune/"}, {"title": "Docker 공식 문서: docker container commit", "url": "https://docs.docker.com/reference/cli/docker/container/commit/"}, {"title": "Docker 공식 문서: docker image inspect", "url": "https://docs.docker.com/reference/cli/docker/image/inspect/"}, {"title": "Docker 공식 문서: docker image save", "url": "https://docs.docker.com/reference/cli/docker/image/save/"}, {"title": "Docker 공식 문서: docker image load", "url": "https://docs.docker.com/reference/cli/docker/image/load/"}, {"title": "Docker 공식 문서: docker container export", "url": "https://docs.docker.com/reference/cli/docker/container/export/"}, {"title": "Docker 공식 문서: docker image import", "url": "https://docs.docker.com/reference/cli/docker/image/import/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 337 AND order_index = 7);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 337, 8, '이미지 ID 만 뽑아 보기', '이미지 `alpine` 의 **ID 하나만** 출력하는 명령입니다. 빈칸에 알맞은 옵션을 채우세요. (`{{.Id}}` 는 상세 정보에서 ID 항목을 뜻합니다)', '상세 정보(JSON) 중 원하는 항목만 템플릿으로 뽑는 옵션이에요. `--format` 의 짧은 이름입니다.', NULL, NULL, '[]', 'fill', '["-f", "-q", "-a", "-l"]', NULL, '`docker image inspect -f 템플릿` 으로 상세 정보에서 원하는 항목만 출력합니다. `-q`, `-a`, `-l` 은 `inspect` 에 없는 옵션이라 오류가 나요. 두 이미지의 `{{.Id}}` 를 비교하면 같은 이미지인지 알 수 있습니다.', '[0]', 'docker image inspect {0} ''{{.Id}}'' alpine', NULL, '[{"title": "Docker 공식 문서: docker image pull", "url": "https://docs.docker.com/reference/cli/docker/image/pull/"}, {"title": "Docker 공식 문서: docker image ls", "url": "https://docs.docker.com/reference/cli/docker/image/ls/"}, {"title": "Docker 공식 문서: docker image tag", "url": "https://docs.docker.com/reference/cli/docker/image/tag/"}, {"title": "Docker 공식 문서: docker image rm", "url": "https://docs.docker.com/reference/cli/docker/image/rm/"}, {"title": "Docker 공식 문서: docker image prune", "url": "https://docs.docker.com/reference/cli/docker/image/prune/"}, {"title": "Docker 공식 문서: docker container commit", "url": "https://docs.docker.com/reference/cli/docker/container/commit/"}, {"title": "Docker 공식 문서: docker image inspect", "url": "https://docs.docker.com/reference/cli/docker/image/inspect/"}, {"title": "Docker 공식 문서: docker image save", "url": "https://docs.docker.com/reference/cli/docker/image/save/"}, {"title": "Docker 공식 문서: docker image load", "url": "https://docs.docker.com/reference/cli/docker/image/load/"}, {"title": "Docker 공식 문서: docker container export", "url": "https://docs.docker.com/reference/cli/docker/container/export/"}, {"title": "Docker 공식 문서: docker image import", "url": "https://docs.docker.com/reference/cli/docker/image/import/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 337 AND order_index = 8);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 337, 9, '이미지를 tar 파일로 저장 (save)', '이미지 `alpine:3.19` 를 `/tmp/work/a.tar` 파일로 저장하세요. 저장된 tar 안에 이미지 정보(`manifest.json`)가 들어 있어야 합니다.', '`docker save` 에 출력 파일 옵션(`-o`)과 이미지 이름을 주면 돼요. 확인은 `tar tf 파일` 로 안의 목록을 보세요.', 'docker save -o /tmp/work/a.tar alpine:3.19
ls -l /tmp/work/a.tar
tar tf /tmp/work/a.tar

# save 는 이미지(레이어+태그 정보)를 tar 하나로 묶는다', '["sh", "-c", "docker rm -f $(docker ps -aq) >/dev/null 2>&1; docker rmi -f $(docker images -aq) >/dev/null 2>&1; rm -rf /tmp/work; mkdir -p /tmp/work; docker pull -q alpine >/dev/null 2>&1; docker pull -q alpine:3.19 >/dev/null 2>&1; true"]', '["sh", "-c", "( [ -s /tmp/work/a.tar ] ) && ( tar tf /tmp/work/a.tar | grep -qx manifest.json ) && ( tar xOf /tmp/work/a.tar manifest.json | grep -q \\"alpine:3.19\\" )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "a.tar 가 있다", "cmd": ["sh", "-c", "[ -s /tmp/work/a.tar ]"]}, {"label": "tar 안에 manifest.json 이 있다", "cmd": ["sh", "-c", "tar tf /tmp/work/a.tar | grep -qx manifest.json"]}, {"label": "manifest 에 alpine:3.19 태그가 있다", "cmd": ["sh", "-c", "tar xOf /tmp/work/a.tar manifest.json | grep -q \\"alpine:3.19\\""]}]', '[{"title": "Docker 공식 문서: docker image pull", "url": "https://docs.docker.com/reference/cli/docker/image/pull/"}, {"title": "Docker 공식 문서: docker image ls", "url": "https://docs.docker.com/reference/cli/docker/image/ls/"}, {"title": "Docker 공식 문서: docker image tag", "url": "https://docs.docker.com/reference/cli/docker/image/tag/"}, {"title": "Docker 공식 문서: docker image rm", "url": "https://docs.docker.com/reference/cli/docker/image/rm/"}, {"title": "Docker 공식 문서: docker image prune", "url": "https://docs.docker.com/reference/cli/docker/image/prune/"}, {"title": "Docker 공식 문서: docker container commit", "url": "https://docs.docker.com/reference/cli/docker/container/commit/"}, {"title": "Docker 공식 문서: docker image inspect", "url": "https://docs.docker.com/reference/cli/docker/image/inspect/"}, {"title": "Docker 공식 문서: docker image save", "url": "https://docs.docker.com/reference/cli/docker/image/save/"}, {"title": "Docker 공식 문서: docker image load", "url": "https://docs.docker.com/reference/cli/docker/image/load/"}, {"title": "Docker 공식 문서: docker container export", "url": "https://docs.docker.com/reference/cli/docker/container/export/"}, {"title": "Docker 공식 문서: docker image import", "url": "https://docs.docker.com/reference/cli/docker/image/import/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 337 AND order_index = 9);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 337, 10, 'tar 파일에서 이미지 불러오기 (load)', '`/tmp/work/img.tar` 에는 `alpine:3.19` 이미지가 담겨 있고, 지금 이 서버에는 그 이미지가 **없습니다**. tar 파일에서 이미지를 불러와 `alpine:3.19` 가 보이게 하세요. (인터넷에서 다시 받지 말고 파일을 쓰세요)', '`docker load` 에 입력 파일 옵션(`-i`)과 파일 경로를 줍니다. 불러온 뒤 `docker images` 에 태그까지 그대로 나타나요.', 'docker load -i /tmp/work/img.tar
docker images alpine

# load 는 save 로 만든 tar 의 이미지와 태그를 그대로 복원한다', '["sh", "-c", "docker rm -f $(docker ps -aq) >/dev/null 2>&1; docker rmi -f $(docker images -aq) >/dev/null 2>&1; rm -rf /tmp/work; mkdir -p /tmp/work; docker pull -q alpine >/dev/null 2>&1; docker pull -q alpine:3.19 >/dev/null 2>&1; docker save -o /tmp/work/img.tar alpine:3.19; docker rmi alpine:3.19 >/dev/null 2>&1; true"]', '["sh", "-c", "( docker image inspect alpine:3.19 >/dev/null 2>&1 )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "alpine:3.19 이미지가 있다", "cmd": ["sh", "-c", "docker image inspect alpine:3.19 >/dev/null 2>&1"]}]', '[{"title": "Docker 공식 문서: docker image pull", "url": "https://docs.docker.com/reference/cli/docker/image/pull/"}, {"title": "Docker 공식 문서: docker image ls", "url": "https://docs.docker.com/reference/cli/docker/image/ls/"}, {"title": "Docker 공식 문서: docker image tag", "url": "https://docs.docker.com/reference/cli/docker/image/tag/"}, {"title": "Docker 공식 문서: docker image rm", "url": "https://docs.docker.com/reference/cli/docker/image/rm/"}, {"title": "Docker 공식 문서: docker image prune", "url": "https://docs.docker.com/reference/cli/docker/image/prune/"}, {"title": "Docker 공식 문서: docker container commit", "url": "https://docs.docker.com/reference/cli/docker/container/commit/"}, {"title": "Docker 공식 문서: docker image inspect", "url": "https://docs.docker.com/reference/cli/docker/image/inspect/"}, {"title": "Docker 공식 문서: docker image save", "url": "https://docs.docker.com/reference/cli/docker/image/save/"}, {"title": "Docker 공식 문서: docker image load", "url": "https://docs.docker.com/reference/cli/docker/image/load/"}, {"title": "Docker 공식 문서: docker container export", "url": "https://docs.docker.com/reference/cli/docker/container/export/"}, {"title": "Docker 공식 문서: docker image import", "url": "https://docs.docker.com/reference/cli/docker/image/import/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 337 AND order_index = 10);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 337, 11, '컨테이너 파일시스템을 내보내고 이미지로 (export, import)', '컨테이너 `src` 의 파일시스템을 `/tmp/work/fs.tar` 로 **내보낸** 뒤(`export`), 그 tar 를 **`flat:1`** 이미지로 **가져오세요**(`import`). 이미지에서 `/note` 가 그대로 보여야 합니다.', '`docker export 컨테이너 -o 파일` 은 컨테이너 파일시스템을 tar 로 내려줘요. `docker import 파일 이름:태그` 는 그 tar 로 이미지를 만듭니다. import 이미지에는 기본 실행 명령이 없으니 확인할 땐 `docker run --rm flat:1 cat /note` 처럼 명령을 직접 적으세요.', 'docker export src -o /tmp/work/fs.tar
tar tf /tmp/work/fs.tar | head
docker import /tmp/work/fs.tar flat:1
docker run --rm flat:1 cat /note

# export/import 는 파일시스템만 옮긴다 (태그·CMD·히스토리는 안 따라옴)', '["sh", "-c", "docker rm -f $(docker ps -aq) >/dev/null 2>&1; docker rmi -f $(docker images -aq) >/dev/null 2>&1; rm -rf /tmp/work; mkdir -p /tmp/work; docker pull -q alpine >/dev/null 2>&1; docker run --name src alpine sh -c ''echo packed > /note'' >/dev/null 2>&1; true"]', '["sh", "-c", "( tar tf /tmp/work/fs.tar | grep -qx note ) && ( docker image inspect flat:1 >/dev/null 2>&1 ) && ( [ \\"$(docker run --rm flat:1 cat /note)\\" = packed ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "fs.tar 안에 note 파일이 있다", "cmd": ["sh", "-c", "tar tf /tmp/work/fs.tar | grep -qx note"]}, {"label": "flat:1 이 있다", "cmd": ["sh", "-c", "docker image inspect flat:1 >/dev/null 2>&1"]}, {"label": "이미지 안 /note 가 packed 다", "cmd": ["sh", "-c", "[ \\"$(docker run --rm flat:1 cat /note)\\" = packed ]"]}]', '[{"title": "Docker 공식 문서: docker image pull", "url": "https://docs.docker.com/reference/cli/docker/image/pull/"}, {"title": "Docker 공식 문서: docker image ls", "url": "https://docs.docker.com/reference/cli/docker/image/ls/"}, {"title": "Docker 공식 문서: docker image tag", "url": "https://docs.docker.com/reference/cli/docker/image/tag/"}, {"title": "Docker 공식 문서: docker image rm", "url": "https://docs.docker.com/reference/cli/docker/image/rm/"}, {"title": "Docker 공식 문서: docker image prune", "url": "https://docs.docker.com/reference/cli/docker/image/prune/"}, {"title": "Docker 공식 문서: docker container commit", "url": "https://docs.docker.com/reference/cli/docker/container/commit/"}, {"title": "Docker 공식 문서: docker image inspect", "url": "https://docs.docker.com/reference/cli/docker/image/inspect/"}, {"title": "Docker 공식 문서: docker image save", "url": "https://docs.docker.com/reference/cli/docker/image/save/"}, {"title": "Docker 공식 문서: docker image load", "url": "https://docs.docker.com/reference/cli/docker/image/load/"}, {"title": "Docker 공식 문서: docker container export", "url": "https://docs.docker.com/reference/cli/docker/container/export/"}, {"title": "Docker 공식 문서: docker image import", "url": "https://docs.docker.com/reference/cli/docker/image/import/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 337 AND order_index = 11);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 337, 12, '이미지를 다른 서버로 옮기는 흐름', '이미지를 오프라인 서버로 옮기는 흐름을 **앞에서 뒤**로 놓으세요.', '내보내는 쪽에서 파일을 만들고 → 파일을 옮기고 → 받는 쪽에서 불러오고 → 확인한 뒤 → 실행해 보는 순서입니다.', NULL, NULL, '[]', 'order', '["원본 서버에서 `docker save -o a.tar 이미지` 로 tar 를 만든다", "만든 `a.tar` 파일을 USB 나 `scp` 로 대상 서버에 옮긴다", "대상 서버에서 `docker load -i a.tar` 로 이미지를 불러온다", "`docker images` 로 이미지와 태그가 보이는지 확인한다", "`docker run` 으로 불러온 이미지가 실제로 실행되는지 확인한다"]', NULL, '**save → 파일 전달 → load → images → run** 순서입니다. `save` 는 태그와 레이어를 tar 하나에 담고, `load` 는 그것을 그대로 복원해요. 복원이 끝난 뒤 `images` 로 목록을, `run` 으로 실제 동작을 확인하면 반입이 끝납니다.', '[0, 1, 2, 3, 4]', NULL, NULL, '[{"title": "Docker 공식 문서: docker image pull", "url": "https://docs.docker.com/reference/cli/docker/image/pull/"}, {"title": "Docker 공식 문서: docker image ls", "url": "https://docs.docker.com/reference/cli/docker/image/ls/"}, {"title": "Docker 공식 문서: docker image tag", "url": "https://docs.docker.com/reference/cli/docker/image/tag/"}, {"title": "Docker 공식 문서: docker image rm", "url": "https://docs.docker.com/reference/cli/docker/image/rm/"}, {"title": "Docker 공식 문서: docker image prune", "url": "https://docs.docker.com/reference/cli/docker/image/prune/"}, {"title": "Docker 공식 문서: docker container commit", "url": "https://docs.docker.com/reference/cli/docker/container/commit/"}, {"title": "Docker 공식 문서: docker image inspect", "url": "https://docs.docker.com/reference/cli/docker/image/inspect/"}, {"title": "Docker 공식 문서: docker image save", "url": "https://docs.docker.com/reference/cli/docker/image/save/"}, {"title": "Docker 공식 문서: docker image load", "url": "https://docs.docker.com/reference/cli/docker/image/load/"}, {"title": "Docker 공식 문서: docker container export", "url": "https://docs.docker.com/reference/cli/docker/container/export/"}, {"title": "Docker 공식 문서: docker image import", "url": "https://docs.docker.com/reference/cli/docker/image/import/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 337 AND order_index = 12);

